/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Funnel Chart Card" (boardui.com/components/funnel-chart-card).
 * No BoardUI source was used.
 */
"use client";

import { useState } from "react";

import {
  CHART_COLORS,
  ChartCardFrame,
  ChartCardHeader,
  MONO_FILL,
  PeriodSelect,
  StatTiles,
  chartColorAt,
  formatInt,
  useTweenedValues,
  type ChartColor,
} from "@/components/motion/funnel-chart-card-shell";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cx } from "@/lib/cx";

/**
 * Funnel Chart Card: a horizontal conversion funnel in the dashboard card
 * shell. Each stage is a column whose band is sized to its share of the top
 * stage and tapers into the next one, with a centred share pill and a tile
 * below. Hovering, focusing or tapping a stage dims the others and swaps the
 * headline for that stage's count and its step conversion from the stage
 * before. The bands are hand-drawn SVG (one per column) because Recharts'
 * funnel is a vertical trapezoid stack.
 */

export type FunnelStage = {
  label: string;
  value: number;
  /** Palette colour; stages cycle the chart palette when omitted. */
  color?: ChartColor;
};

export type FunnelRange = {
  id: string;
  /** Text in the period select, e.g. "Last 7 days". */
  label: string;
  /** Top of the funnel first. */
  stages: FunnelStage[];
  /** Percent change for the headline chip. */
  delta?: number;
  /** Headline when nothing is hovered; defaults to the top stage's value. */
  headline?: number;
};

export type FunnelShape = "curved" | "sharp";

/** Three demo periods of a sign-up funnel. */
export const SIGNUP_FUNNEL_RANGES: FunnelRange[] = [
  {
    id: "7d",
    label: "Last 7 days",
    delta: 5.2,
    stages: [
      { label: "Link opened", value: 197 },
      { label: "Started", value: 110 },
      { label: "Completed", value: 77 },
      { label: "Converted", value: 38 },
    ],
  },
  {
    id: "30d",
    label: "Last 30 days",
    delta: 8.4,
    stages: [
      { label: "Link opened", value: 842 },
      { label: "Started", value: 512 },
      { label: "Completed", value: 289 },
      { label: "Converted", value: 171 },
    ],
  },
  {
    id: "90d",
    label: "Last 90 days",
    delta: -2.1,
    stages: [
      { label: "Link opened", value: 2604 },
      { label: "Started", value: 1186 },
      { label: "Completed", value: 903 },
      { label: "Converted", value: 412 },
    ],
  },
];

/** Outer edge of the layered halo, in px above and below the core band. */
const EDGE = 12;
/** The two halo layers: extra half-height in px and opacity. */
const LAYERS = [
  { grow: EDGE, opacity: 0.16 },
  { grow: EDGE / 2, opacity: 0.32 },
] as const;
/** Where the curved band stops running flat and starts easing, in 0-100 column units. */
const FLAT = 50;
/** Height of the faint track behind sharp columns, in px. */
const SHARP_TRACK = 36;
/** Thinnest core band so a 1% stage still reads as a line. */
const MIN_CORE = 2;

const pct = (part: number, whole: number) => (whole > 0 ? Math.round((part / whole) * 100) : 0);
const n = (value: number) => Math.round(value * 100) / 100;

/** One column's band from its own height `h0` into the next stage's `h1`. */
function bandPath(h0: number, h1: number, mid: number, shape: FunnelShape) {
  const t0 = n(mid - h0 / 2);
  const b0 = n(mid + h0 / 2);
  const t1 = n(mid - h1 / 2);
  const b1 = n(mid + h1 / 2);
  if (shape === "sharp") return `M0 ${t0}L100 ${t1}L100 ${b1}L0 ${b0}Z`;
  const c = (FLAT + 100) / 2;
  return `M0 ${t0}H${FLAT}C${c} ${t0} ${c} ${t1} 100 ${t1}V${b1}C${c} ${b1} ${c} ${b0} ${FLAT} ${b0}H0Z`;
}

export type FunnelChartCardProps = {
  /** Card label shown while no stage is active. */
  title?: string;
  /** Periods, each with its own stages; the select appears with two or more. */
  ranges?: FunnelRange[];
  /** Plain stage list; when set it replaces `ranges` and the select is hidden. */
  stages?: FunnelStage[];
  /** Headline chip when `stages` is used. */
  delta?: number;
  /** Controlled period id. */
  range?: string;
  /** Initial period id when uncontrolled; defaults to the first range. */
  defaultRange?: string;
  onRangeChange?: (id: string) => void;
  /** "curved" eases each band into the next with layered edges; "sharp" draws plain trapezoids. */
  shape?: FunnelShape;
  /** Paint every stage in the text colour and drop the swatches. */
  mono?: boolean;
  /** Chart height in px, halo included. */
  chartHeight?: number;
  className?: string;
};

// #region critical
export function FunnelChartCard({
  title = "Sign-up funnel",
  ranges = SIGNUP_FUNNEL_RANGES,
  stages: stagesProp,
  delta: deltaProp,
  range: rangeProp,
  defaultRange,
  onRangeChange,
  shape = "curved",
  mono = false,
  chartHeight = 160,
  className,
}: FunnelChartCardProps) {
  const reduced = useReducedMotion();
  const [innerRange, setInnerRange] = useState(defaultRange ?? ranges[0]?.id ?? "");
  const rangeId = rangeProp ?? innerRange;
  const activeRange = ranges.find((r) => r.id === rangeId) ?? ranges[0];
  const stages = stagesProp ?? activeRange?.stages ?? [];
  const delta = stagesProp ? deltaProp : activeRange?.delta;

  const [hovered, setHovered] = useState<number | null>(null);
  const [pinned, setPinned] = useState<number | null>(null);
  const active = hovered ?? (pinned !== null && pinned < stages.length ? pinned : null);

  const top = stages[0]?.value ?? 0;
  const coreMax = chartHeight - EDGE * 2;
  const mid = chartHeight / 2;
  // Shares are tweened, not heights, so a new period re-grows from the old shape.
  const shares = useTweenedValues(
    stages.map((s) => (top > 0 ? s.value / top : 0)),
    { disabled: reduced },
  );
  const heights = shares.map((share) => Math.max(MIN_CORE, share * coreMax));

  const activeStage = active !== null ? stages[active] : undefined;
  const prevStage = active !== null && active > 0 ? stages[active - 1] : undefined;
  const headline = activeStage ? activeStage.value : (!stagesProp && activeRange?.headline) || top;

  const selectRange = (id: string) => {
    if (rangeProp === undefined) setInnerRange(id);
    setPinned(null);
    onRangeChange?.(id);
  };

  return (
    <ChartCardFrame className={className} aria-label={title}>
      <ChartCardHeader
        label={activeStage ? activeStage.label : title}
        value={headline}
        valueKey={active ?? "total"}
        delta={activeStage ? undefined : delta}
        note={
          activeStage
            ? prevStage
              ? `${pct(activeStage.value, prevStage.value)}% of ${prevStage.label}`
              : "Top of funnel"
            : undefined
        }
        action={
          !stagesProp && ranges.length > 1 ? (
            <PeriodSelect options={ranges} selectedId={activeRange?.id ?? ""} onChange={selectRange} />
          ) : undefined
        }
      />

      <div
        role="group"
        aria-label={`${title} stages`}
        className="flex gap-0.5 px-2"
        style={{ height: chartHeight }}
        onPointerLeave={() => setHovered(null)}
      >
        {stages.map((stage, index) => {
          const color = CHART_COLORS[chartColorAt(index, stage.color)];
          const isActive = active === index;
          const fill = mono ? (isActive ? "var(--color-text-primary)" : MONO_FILL) : isActive ? color.active : color.fill;
          const h0 = heights[index] ?? MIN_CORE;
          const h1 = heights[index + 1] ?? h0;
          const share = pct(stage.value, top);
          const prev = index > 0 ? stages[index - 1] : undefined;
          return (
            <button
              key={`${stage.label}-${index}`}
              type="button"
              aria-pressed={pinned === index}
              aria-label={`${stage.label}: ${formatInt(stage.value)}, ${share}% of ${stages[0]?.label ?? "top"}${
                prev ? `, ${pct(stage.value, prev.value)}% of ${prev.label}` : ""
              }`}
              onPointerEnter={() => setHovered(index)}
              onFocus={() => setHovered(index)}
              onBlur={() => setHovered(null)}
              onClick={() => setPinned((p) => (p === index ? null : index))}
              className={cx(
                "relative min-w-0 flex-1 cursor-pointer rounded-md outline-none",
                "transition-opacity duration-200 ease-out motion-reduce:transition-none",
                "focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                active !== null && !isActive && "opacity-35",
              )}
            >
              <svg
                aria-hidden
                viewBox={`0 0 100 ${chartHeight}`}
                preserveAspectRatio="none"
                className="absolute inset-0 size-full overflow-visible"
              >
                {shape === "sharp" ? (
                  <rect
                    x={0}
                    y={mid - SHARP_TRACK / 2}
                    width={100}
                    height={SHARP_TRACK}
                    style={{ fill: mono ? MONO_FILL : color.fill, opacity: 0.18 }}
                  />
                ) : (
                  LAYERS.map((layer) => (
                    <path
                      key={layer.grow}
                      d={bandPath(h0 + layer.grow * 2, h1 + layer.grow * 2, mid, shape)}
                      style={{ fill: mono ? MONO_FILL : color.fill, opacity: layer.opacity }}
                    />
                  ))
                )}
                <path
                  d={bandPath(h0, h1, mid, shape)}
                  className="transition-[fill] duration-200 ease-out motion-reduce:transition-none"
                  style={{ fill }}
                />
              </svg>
              <span
                aria-hidden
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-background-primary-default px-1.5 py-px text-caption-1-medium text-text-primary tabular-nums shadow-xs"
              >
                {share}%
              </span>
            </button>
          );
        })}
      </div>

      <StatTiles
        columns={Math.max(1, stages.length)}
        activeIndex={active}
        onActiveChange={setHovered}
        items={stages.map((stage, index) => ({
          id: `${stage.label}-${index}`,
          label: stage.label,
          value: formatInt(stage.value),
          color: mono ? null : chartColorAt(index, stage.color),
        }))}
      />
    </ChartCardFrame>
  );
}
// #endregion

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Funnel Chart Card" (boardui.com/components/funnel-chart-card).
 * No BoardUI source was used.
 */
"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { RiCalendarLine } from "@remixicon/react";

import { Chip } from "@/components/motion/chip";
import { Select, SelectItem } from "@/components/motion/select";
import { useCountUp } from "@/hooks/use-count-up";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cx } from "@/lib/cx";
import { easeOutCubic } from "@/lib/easing";

/**
 * The dashboard chart-card shell shared by the funnel, Sankey, stage bars,
 * radial and speedometer cards: a secondary-surface frame, a header with a
 * count-up headline, a delta chip and a period select, and a wrap of white
 * stat tiles that stay in step with whatever the chart has under the pointer.
 */

export type ChartColor = "lime" | "blue" | "purple" | "pink" | "yellow" | "emerald" | "sky" | "indigo" | "teal";

/** The order stages and series take their colour in when none is given. */
export const CHART_COLOR_ORDER: readonly ChartColor[] = [
  "lime",
  "blue",
  "purple",
  "pink",
  "yellow",
  "emerald",
  "sky",
  "indigo",
  "teal",
];

/** CSS colour for SVG fills, the darker hover tone, and a static swatch class. */
export const CHART_COLORS: Record<ChartColor, { fill: string; active: string; swatch: string }> = {
  lime: { fill: "var(--color-chart-2)", active: "var(--color-chart-2-active)", swatch: "bg-chart-2" },
  blue: { fill: "var(--color-chart-6)", active: "var(--color-chart-6-active)", swatch: "bg-chart-6" },
  purple: { fill: "var(--color-chart-5)", active: "var(--color-chart-5-active)", swatch: "bg-chart-5" },
  pink: { fill: "var(--color-chart-3)", active: "var(--color-chart-3-active)", swatch: "bg-chart-3" },
  yellow: { fill: "var(--color-chart-8)", active: "var(--color-chart-8-active)", swatch: "bg-chart-8" },
  emerald: { fill: "var(--color-chart-7)", active: "var(--color-chart-7-active)", swatch: "bg-chart-7" },
  sky: { fill: "var(--color-chart-4)", active: "var(--color-chart-4-active)", swatch: "bg-chart-4" },
  indigo: { fill: "var(--color-chart-9)", active: "var(--color-chart-9-active)", swatch: "bg-chart-9" },
  teal: { fill: "var(--color-chart-1)", active: "var(--color-chart-1-active)", swatch: "bg-chart-1" },
};

/** Single-ink fill for `mono` cards: mid grey on light, light grey on dark. */
export const MONO_FILL = "var(--color-text-secondary)";

/** The colour for the item at `index`, cycling the palette unless overridden. */
export function chartColorAt(index: number, override?: ChartColor): ChartColor {
  return override ?? CHART_COLOR_ORDER[index % CHART_COLOR_ORDER.length] ?? "lime";
}

export const formatInt = (value: number) => Math.round(value).toLocaleString("en-US");

/** "+5.2%" in lime, "-1.8%" in rose, "0%" in neutral. */
export function deltaChip(delta: number) {
  const rounded = Math.round(delta * 10) / 10;
  if (rounded === 0) return { label: "0%", color: "neutral" as const };
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : ("rose" as const),
  };
}

/**
 * Tweens a list of numbers towards `targets` with an ease-out cubic, starting
 * from zeros on mount so the chart grows in. Interrupted tweens restart from
 * wherever the previous one had got to. With `disabled` it returns the
 * targets as they are.
 */
export function useTweenedValues(targets: readonly number[], { duration = 520, disabled = false } = {}) {
  const [current, setCurrent] = useState<number[]>(() => targets.map(() => 0));
  const fromRef = useRef<number[]>(current);
  const key = targets.join(",");

  useEffect(() => {
    if (disabled) {
      fromRef.current = [...targets];
      return;
    }
    const goal = key === "" ? [] : key.split(",").map(Number);
    const from = fromRef.current;
    const start = performance.now();
    let raf = 0;
    const tick = (now: number) => {
      const t = Math.min(1, Math.max(0, (now - start) / duration));
      const eased = easeOutCubic(t);
      const next = goal.map((value, index) => {
        const origin = from[index] ?? 0;
        return origin + (value - origin) * eased;
      });
      fromRef.current = next;
      setCurrent(next);
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
    // `key` carries the targets' contents; the array identity changes every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, duration, disabled]);

  if (disabled) return [...targets];
  return targets.map((_, index) => current[index] ?? 0);
}

/* ----------------------------------------------------------------- frame */

export function ChartCardFrame({
  className,
  children,
  "aria-label": ariaLabel,
}: {
  className?: string;
  children: ReactNode;
  "aria-label"?: string;
}) {
  return (
    <section
      aria-label={ariaLabel}
      className={cx("flex min-w-0 flex-col gap-4 rounded-2xl bg-background-secondary-default p-2", className)}
    >
      {children}
    </section>
  );
}

/* ---------------------------------------------------------------- header */

export type ChartCardHeaderProps = {
  /** Muted label above the figure: the card title, or the hovered item's name. */
  label: ReactNode;
  /** The headline number; it counts to every new value. */
  value: number;
  /** Turns the counted number into text, e.g. hours or money. */
  formatValue?: (value: number) => string;
  /** Percent change for the chip; omit to hide the chip. */
  delta?: number;
  /** Free-form chip text that replaces the delta chip (e.g. a step conversion). */
  note?: ReactNode;
  /** Changes whenever the headline swaps subject, so the fade replays. */
  valueKey?: string | number;
  /** Right-hand slot, usually a PeriodSelect. */
  action?: ReactNode;
};

export function ChartCardHeader({
  label,
  value,
  formatValue = formatInt,
  delta,
  note,
  valueKey,
  action,
}: ChartCardHeaderProps) {
  const reduced = useReducedMotion();
  // A 1ms count lands on the next frame: the number still updates, it just doesn't roll.
  const display = useCountUp(value, reduced ? 1 : 320);
  const chip = delta === undefined ? null : deltaChip(delta);

  return (
    <div className="flex items-start justify-between gap-3 px-2 pt-2">
      <div className="flex min-w-0 flex-col gap-0.5">
        <p className="truncate text-body-medium text-text-secondary">{label}</p>
        <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
          <p
            key={valueKey}
            className="animate-number-fade text-title-1-regular whitespace-nowrap text-text-primary tabular-nums motion-reduce:animate-none"
          >
            {formatValue(display)}
          </p>
          {note !== undefined ? (
            <Chip variant="bold" color="neutral" className="tabular-nums">
              {note}
            </Chip>
          ) : chip ? (
            <Chip variant="bold" color={chip.color} className="tabular-nums">
              {chip.label}
            </Chip>
          ) : null}
        </div>
      </div>
      {action ? <div className="shrink-0">{action}</div> : null}
    </div>
  );
}

/* ---------------------------------------------------------- period select */

export type PeriodOption = { id: string; label: string };

export function PeriodSelect({
  options,
  selectedId,
  onChange,
  "aria-label": ariaLabel = "Period",
}: {
  options: readonly PeriodOption[];
  selectedId: string;
  onChange: (id: string) => void;
  "aria-label"?: string;
}) {
  return (
    <Select
      aria-label={ariaLabel}
      size="sm"
      selectedKey={selectedId}
      onSelectionChange={(key) => {
        if (key !== null) onChange(String(key));
      }}
      triggerClassName="gap-1.5 px-2.5 py-1.5 text-body-medium"
      popoverClassName="w-44"
      renderValue={({ selectedText }) => (
        <>
          <RiCalendarLine aria-hidden className="size-4 shrink-0 text-text-secondary" />
          <span className="truncate">{selectedText}</span>
        </>
      )}
    >
      {options.map((option) => (
        <SelectItem key={option.id} id={option.id} textValue={option.label}>
          {option.label}
        </SelectItem>
      ))}
    </Select>
  );
}

/* ------------------------------------------------------------- stat tiles */

export type StatTileItem = {
  id: string;
  label: string;
  value: ReactNode;
  /** Swatch colour; null hides the swatch (mono cards). */
  color: ChartColor | null;
};

// #region critical
/**
 * White tiles under the chart. Hovering one reports its index, so the chart
 * and the headline follow; while another item is active the rest fade back.
 * `columns` is the most tiles per row: tiles keep a 120px minimum and grow to
 * fill, so a narrow card wraps to two per row and a short last row stretches.
 */
export function StatTiles({
  items,
  activeIndex,
  onActiveChange,
  columns = 4,
  className,
}: {
  items: readonly StatTileItem[];
  activeIndex: number | null;
  onActiveChange?: (index: number | null) => void;
  columns?: number;
  className?: string;
}) {
  const basis = `calc((100% - ${(columns - 1) * 8}px) / ${columns})`;
  return (
    <ul className={cx("flex flex-wrap gap-2", className)} onPointerLeave={() => onActiveChange?.(null)}>
      {items.map((item, index) => {
        const dimmed = activeIndex !== null && activeIndex !== index;
        const style: CSSProperties = { flexBasis: basis };
        return (
          <li
            key={item.id}
            style={style}
            onPointerEnter={() => onActiveChange?.(index)}
            data-active={activeIndex === index || undefined}
            className={cx(
              "flex min-w-[120px] grow flex-col gap-0.5 rounded-2lg bg-background-primary-default px-2.5 py-2",
              "transition-opacity duration-200 ease-out motion-reduce:transition-none",
              dimmed && "opacity-45",
            )}
          >
            <span className="flex min-w-0 items-center gap-1.5 text-body-regular text-text-secondary">
              {item.color ? (
                <span aria-hidden className={cx("size-2.5 shrink-0 rounded-[3px]", CHART_COLORS[item.color].swatch)} />
              ) : null}
              <span className="truncate">{item.label}</span>
            </span>
            <span className="text-body-medium text-text-primary tabular-nums">{item.value}</span>
          </li>
        );
      })}
    </ul>
  );
}
// #endregion
